import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { mix, positionLocal, smoothstep, texture, uv, vec3, normalLocal } from 'three/tsl';
import { gsap } from 'gsap';

function hexToRgb(hex) {
  const value = String(hex || '#000000').replace('#', '');
  const normalized = value.length === 3
    ? value.split('').map((c) => c + c).join('')
    : value;
  const integer = parseInt(normalized, 16);
  return [
    ((integer >> 16) & 255) / 255,
    ((integer >> 8) & 255) / 255,
    (integer & 255) / 255
  ];
}

function colorNode(hex) {
  const [r, g, b] = hexToRgb(hex);
  return vec3(r, g, b);
}

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    MeshBasicMaterial,
    MeshStandardMaterial,
    LineBasicMaterial,
    EdgesGeometry,
    LineSegments,
    AmbientLight,
    PointLight,
    Color,
    Vector3
  } = THREE;

  const visualSpec = config.intent?.visualSpec || {};
  const colors = {
    ink: visualSpec.colors?.ink || '#16161d',
    paper: visualSpec.colors?.paper || '#e8ecf2',
    accent: visualSpec.colors?.accent || '#ff2a38',
    surface: visualSpec.colors?.surface || '#0b0b10'
  };

  const root = new Group();
  root.name = config.id || 'pricing-list-row';
  root.userData = root.userData || {};
  root.userData.handlers = {};

  const resources = [];
  const primitiveResults = [];
  const timelines = [];

  const stage = new Group();
  stage.name = 'pricing-row-stage';
  root.add(stage);

  const backdropGeometry = new PlaneGeometry(7, 6, 1, 1);
  const backdropMaterial = new MeshBasicNodeMaterial();
  const gradientY = smoothstep(0.0, 1.0, uv().y);
  const lower = mix(colorNode(colors.surface), colorNode(colors.ink), gradientY);
  const upper = mix(lower, colorNode(colors.accent), smoothstep(0.72, 1.0, uv().y).mul(0.08));
  backdropMaterial.colorNode = upper;
  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.z = -2.5;
  stage.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const contactGeometry = new PlaneGeometry(5.5, 1.8, 1, 1);
  const contactMaterial = new MeshBasicMaterial({
    color: new Color(colors.surface),
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });
  const contact = new Mesh(contactGeometry, contactMaterial);
  contact.name = 'radial-contact-shadow';
  contact.scale.set(1.0, 0.34, 1);
  contact.position.set(0, -0.78, -1.76);
  stage.add(contact);
  resources.push(contactGeometry, contactMaterial);

  const row = new Group();
  row.name = 'pricing-list-row-content';
  row.position.z = -0.8;
  stage.add(row);

  const plateGeometry = new BoxGeometry(5.9, 1.22, 0.12, 1, 1, 1);
  const plateMaterial = new MeshStandardMaterial({
    color: new Color(colors.surface),
    roughness: 0.72,
    metalness: 0.42
  });
  const plate = new Mesh(plateGeometry, plateMaterial);
  plate.name = 'machined-metal-row-plate';
  row.add(plate);
  resources.push(plateGeometry, plateMaterial);

  const imageGeometry = new PlaneGeometry(5.72, 1.04, 64, 64);
  const imageMaterial = new MeshStandardNodeMaterial({
    color: new Color(colors.paper),
    roughness: 0.62,
    metalness: 0.24
  });
  imageMaterial.positionNode = positionLocal.add(
    normalLocal.mul(0.08)
  );
  const imagePlane = new Mesh(imageGeometry, imageMaterial);
  imagePlane.name = 'layered-parallax-surface';
  imagePlane.position.z = 0.1;
  row.add(imagePlane);
  resources.push(imageGeometry, imageMaterial);

  const frameMaterial = new MeshStandardMaterial({
    color: new Color(colors.ink),
    roughness: 0.58,
    metalness: 0.52
  });
  const frameParts = [
    [5.92, 0.07, 0.16, 0, 0.59, 0.14],
    [5.92, 0.07, 0.16, 0, -0.59, 0.14],
    [0.07, 1.18, 0.16, -2.92, 0, 0.14],
    [0.07, 1.18, 0.16, 2.92, 0, 0.14]
  ];
  for (const [sx, sy, sz, x, y, z] of frameParts) {
    const geometry = new BoxGeometry(sx, sy, sz);
    const mesh = new Mesh(geometry, frameMaterial);
    mesh.position.set(x, y, z);
    row.add(mesh);
    resources.push(geometry);
  }
  resources.push(frameMaterial);

  const dividerGeometry = new PlaneGeometry(5.15, 0.012, 1, 1);
  const dividerMaterial = new MeshBasicMaterial({
    color: new Color(colors.paper),
    transparent: true,
    opacity: 0.28
  });
  const divider = new Mesh(dividerGeometry, dividerMaterial);
  divider.name = 'subtle-divider';
  divider.position.set(0, -0.22, 0.25);
  row.add(divider);
  resources.push(dividerGeometry, dividerMaterial);

  const accentGeometry = new BoxGeometry(0.055, 0.86, 0.035);
  const accentMaterial = new MeshStandardMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 1.35,
    roughness: 0.52,
    metalness: 0.34
  });
  const accentBar = new Mesh(accentGeometry, accentMaterial);
  accentBar.name = 'signal-red-accent-rim';
  accentBar.position.set(-2.68, 0.03, 0.3);
  row.add(accentBar);
  resources.push(accentGeometry, accentMaterial);

  const edgeGeometry = new EdgesGeometry(new BoxGeometry(5.9, 1.22, 0.12));
  const edgeMaterial = new LineBasicMaterial({
    color: new Color(colors.paper),
    transparent: true,
    opacity: 0.18
  });
  const edges = new LineSegments(edgeGeometry, edgeMaterial);
  edges.position.z = 0.22;
  row.add(edges);
  resources.push(edgeGeometry, edgeMaterial);

  const key = new PointLight(new Color(colors.paper), 0.72, 8, 2);
  key.position.set(-2.8, 2.1, 3.2);
  stage.add(key);

  const rim = new PointLight(new Color(colors.accent), 0.72, 6, 2);
  rim.position.set(3.0, 0.3, 2.0);
  stage.add(rim);

  const ambient = new AmbientLight(new Color(colors.paper), 0.18);
  stage.add(ambient);

  const items = config.textContent ?? visualSpec.textContent ?? [];
  const textGroup = new Group();
  textGroup.name = 'row-text';
  textGroup.position.set(-2.25, 0.08, 0.34);
  row.add(textGroup);

  const textObjects = [];
  for (const item of items) {
    const content = typeof item.text === 'string' ? item.text : '';
    if (!content) continue;

    const role = item.role || 'body';
    const fontSize = item.typography?.fontSize ||
      (role === 'hero' ? 0.62 :
       role === 'headline' ? 0.34 :
       role === 'subhead' ? 0.2 :
       role === 'caption' ? 0.09 : 0.13);

    const textObject = ctx.fontAtlas.createText(content, {
      fontSize,
      color: role === 'caption' ? colors.accent : colors.paper,
      align: item.typography?.align || 'left',
      maxWidthPx: item.typography?.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx
    });

    textObject.position.y = textObjects.length === 0 ? 0.18 : -0.18;
    textGroup.add(textObject);
    textObjects.push(textObject);
  }

  const imageUrl = config.imageUrl || visualSpec.imageUrl;
  const depthMapUrl = config.depthMapUrl || visualSpec.depthMapUrl;

  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((imageTexture) => {
      if (!root.userData.cleaned) {
        imageMaterial.map = imageTexture;
        imageMaterial.colorNode = texture(imageTexture, uv());
        imageMaterial.needsUpdate = true;
        resources.push(imageTexture);
      }
    }).catch(() => {});
  }

  if (depthMapUrl) {
    ctx.textureLoader.loadTexture(depthMapUrl).then((depthTexture) => {
      if (!root.userData.cleaned) {
        const depthNode = texture(depthTexture, uv());
        imageMaterial.positionNode = positionLocal.add(
          normalLocal.mul(depthNode.r.sub(0.5).mul(0.14))
        );
        imageMaterial.needsUpdate = true;
        resources.push(depthTexture);
      }
    }).catch(() => {});
  }

  const entrance = gsap.timeline({ paused: false });
  entrance.fromTo(
    row.position,
    { y: -0.4 },
    { y: 0, duration: 0.7, ease: 'power3.out' }
  );
  entrance.fromTo(
    row.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    '<'
  );
  timelines.push(entrance);

  const primitiveConfig = config.cinematicPrimitives || [];
  for (const primitive of primitiveConfig) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler !== 'function') continue;
    const result = handler(root, primitive.params || {});
    if (result) {
      primitiveResults.push(result);
      if (result.timeline) timelines.push(result.timeline);
    }
  }

  root.userData.handlers.hover = (active = true) => {
    const targetY = active ? 0.15 : 0;
    gsap.to(row.position, {
      y: targetY,
      duration: 0.3,
      ease: 'power2.out',
      overwrite: true
    });
  };

  root.userData.handlers.click = () => {
    ctx.emit('hub-pricing.select', {
      nodeId: config.id || 'pricing-list-row'
    });
  };

  root.userData.cleanup = () => {
    if (root.userData.cleaned) return;
    root.userData.cleaned = true;

    for (const timeline of timelines) {
      if (timeline?.kill) timeline.kill();
    }

    for (const result of primitiveResults) {
      if (result?.cleanup) result.cleanup();
    }

    for (const resource of resources) {
      if (resource?.dispose) resource.dispose();
    }

    root.clear();
  };

  return root;
}
